      "content": "{\n  \"name\": \"dsh-auto-review\",\n  \"version\": \"0.15.0\",\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"description\": \"Second-model AI auto-review for DeepSeek Harness approval requests: a read-only reviewer subagent or the local non-generative Phocinae-Largha-150M-v1 decision model decides allow/deny on the approval answerer chain, with fail-closed fallback and full session-log audit.\",\n  \"private\": false,\n  \"author\": {\n    \"name\": \"PerryLink\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/PerryLink/dsh-auto-review.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/PerryLink/dsh-auto-review/issues\"\n  },\n  \"homepage\": \"https://github.com/PerryLink/dsh-auto-review#readme\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"bin\": {\n    \"dsh-eval\": \"./bin/dsh-eval.mjs\",\n    \"dsh-auto-review-mcp\": \"./bin/dsh-auto-review-mcp.mjs\"\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./mcp\": {\n      \"types\": \"./lib/types/mcp/index.d.ts\",\n      \"default\": \"./lib/mcp.js\"\n    },\n    \"./invariant\": {\n      \"types\": \"./lib/types/invariant.d.ts\",\n      \"default\": \"./lib/invariant.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./eval\": {\n      \"types\": \"./lib/types/eval/index.d.ts\",\n      \"default\": \"./lib/eval.js\"\n    },\n    \"./eval-cli\": {\n      \"types\": \"./lib/types/eval/cli.d.ts\",\n      \"default\": \"./lib/eval-cli.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"bin\",\n    \"eval\",\n    \"fixtures\",\n    \"bench\",\n    \"cordis.patch.yml\",\n    \"CHANGELOG.md\",\n    \"README.md\",\n    \"README-zh.md\",\n    \"README-es.md\",\n    \"README-pt.md\",\n    \"README-hi.md\",\n    \"LICENSE\",\n    \"PRIVACY.md\",\n    \"icon.svg\"\n  ],\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-conversation\"\n      ]\n    }\n  },\n  \"dshWorkshop\": {\n    \"schema\": \"omdsh-workshop-package/v1\",\n    \"type\": \"plugin\",\n    \"integration\": {\n      \"protocol\": \"harness-profile\",\n      \"artifact\": \"cordis.patch.yml\"\n    },\n    \"install\": {\n      \"mode\": \"transactional\",\n      \"adapter\": \"profile-bundle\",\n      \"failurePolicy\": \"generation-rollback\",\n      \"touchesCurrentBeforeActivation\": false\n    },\n    \"lifecycle\": {\n      \"activation\": \"restart-profile\",\n      \"dispose\": \"supported\"\n    },\n    \"permissions\": [\n      \"session:append\",\n      \"approval:answer\",\n      \"subagent:spawn\",\n      \"command:register\",\n      \"tools:observe\"\n    ],\n    \"compatibility\": {\n      \"dshVersions\": [\n        \"0.1.2-rc.1\",\n        \"0.1.3-alpha.2\",\n        \"0.1.5-rc.2\",\n        \"0.1.7-alpha.2\",\n        \"0.1.7-rc.1\",\n        \"0.1.7-rc.2\",\n        \"0.2.1-alpha.1\"\n      ]\n    },\n    \"capability\": {\n      \"id\": \"auto-review-command\",\n      \"kind\": \"command\",\n      \"invocation\": \"/auto-review status\",\n      \"expected\": \"reports the session's auto-review switch state, the per-turn AI-verdict and reviewer-failure budgets, any active circuit trip, and the cumulative allows/denies/fallbacks/never-rejects\"\n    },\n    \"evidence\": {\n      \"install\": \"docs/omdsh-evidence/install.md\",\n      \"failureIsolation\": null,\n      \"hotReload\": null,\n      \"remove\": \"docs/omdsh-evidence/remove.md\"\n    }\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"approval\",\n    \"auto-review\",\n    \"second-model\",\n    \"ai-safety\",\n    \"sandbox\",\n    \"subagent\",\n    \"phocinae\",\n    \"decision-model\",\n    \"local-inference\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.2.1-0 <0.3.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5-alpha.1\",\n    \"@deepseek-ai/dsh-agent\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-brand\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-commands\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-session\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-session-projection\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-subagent\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/dsh-user-approval\": \">=0.1.2-rc.1 <0.2.0 || >=0.1.5-alpha.1 <0.2.0 || >=0.1.6-0 <0.2.0 || >=0.1.7-0 <0.2.0 || >=0.2.0-0 <0.3.0 || >=0.2.1-0 <0.3.0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.5-alpha.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-conversation\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"yaml\": \"^2.8.2\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.5-alpha.1\",\n    \"@deepseek-ai/cordis-plugin-group\": \"^1.0.5-alpha.1\",\n    \"@deepseek-ai/cordis-plugin-include\": \"^1.0.10-alpha.1\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"^1.0.6-alpha.1\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-agent-spine-demo\": \"0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-app-boot\": \"0.2.1-alpha.1\",\n    \"@deepseek-ai/dsh-brand\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-c